import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.Bg-Zxr5O.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/CHISQUARE.md","filePath":"manual-en/CHISQUARE.md","lastUpdated":1785684581000}'),n={name:"manual-en/CHISQUARE.md"};function r(i,e,d,h,c,l){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h4 id="_15-12-2-chi-square-test" tabindex="-1">15.12.2 Chi-square Test <a class="header-anchor" href="#_15-12-2-chi-square-test" aria-label="Permalink to &quot;15.12.2 Chi-square Test&quot;">​</a></h4><pre><code>     [ /CHISQUARE=var_list[(lo,hi)] [/EXPECTED={EQUAL|f1, f2 … fn}] ]
</code></pre><p>The <code>/CHISQUARE</code> subcommand produces a chi-square statistic for the differences between the expected and observed frequencies of the categories of a variable. Optionally, a range of values may appear after the variable list. If a range is given, then non integer values are truncated, and values outside the specified range are excluded from the analysis.</p><p>The <code>/EXPECTED</code> subcommand specifies the expected values of each category. There must be exactly one non-zero expected value, for each observed category, or the <code>EQUAL</code> keyword must be specified. You may use the notation <code>n*f</code> to specify n consecutive expected categories all taking a frequency of f. The frequencies given are proportions, not absolute frequencies. The sum of the frequencies need not be 1. If no <code>/EXPECTED</code> subcommand is given, then equal frequencies are expected.</p><h4 id="_15-12-2-1-chi-square-example" tabindex="-1">15.12.2.1 Chi-square Example <a class="header-anchor" href="#_15-12-2-1-chi-square-example" aria-label="Permalink to &quot;15.12.2.1 Chi-square Example&quot;">​</a></h4><p>A researcher wishes to investigate whether there are an equal number of persons of each sex in a population. The sample chosen for invesigation is that from the physiology.sav dataset. The null hypothesis for the test is that the population comprises an equal number of males and females. The analysis is performed as shown in Example 15.5.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>get file=&#39;physiology.sav&#39;.  npar test      /chisquare=sex.</span></span></code></pre></div><p><strong>Example 15.5:</strong> Performing a chi-square test to check for equal distribution of sexes</p><p>There is only one test variable, <em>viz:</em> <strong>sex</strong>. The other variables in the dataset are ignored.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span></code></pre></div><p><strong>Screenshot 15.4:</strong> Performing a chi-square test using the graphic user interface</p><p>In Result 15.4 the summary box shows that in the sample, there are more males than females. However the significance of chi-square result is greater than 0.05 — the most commonly accepted p-value — and therefore there is not enough evidence to reject the null hypothesis and one must conclude that the evidence does not indicate that there is an imbalance of the sexes in the population.</p><table tabindex="0"><thead><tr><th>Value</th><th>Observed N</th><th>Expected N</th><th>Residual</th></tr></thead><tbody><tr><td>Male</td><td>22</td><td>20.00</td><td>2.00</td></tr><tr><td>Female</td><td>18</td><td>20.00</td><td>-2.00</td></tr><tr><td>Total</td><td>40</td><td></td><td></td></tr><tr><td></td><td>Chi-square</td><td>df</td><td>Asymp. Sig.</td></tr><tr><td>Sex of subject</td><td>.40</td><td>1</td><td>.527</td></tr></tbody></table><p><strong>Result 15.4:</strong> The results of running a chi-square test on <strong>sex</strong></p>`,14)])])}const f=t(n,[["render",r]]);export{u as __pageData,f as default};
